import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, random, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// Each ray of the burst firing, in launch order. Frames on the 30 fps scene
// timeline, after `delay` and `speed`. The ids are public: a saved `timing`
// prop refers to them.

type TrimBurstElementId = `ray:${number}`;

interface TrimBurstTimingProps {
  count?: number;
  jitter?: number;
}

/** Frames a ray takes from leaving the centre to vanishing at its reach. */
const TRIM_LIFE = 15;
/** Frames the tail waits before chasing the head. */
const TRIM_LAG = 3;
/** Launch spread across all rays at full jitter. */
const STAGGER = 6;
const MAX_COUNT = 32;
const COUNT = 8;
const JITTER = 0.5;

const finite = (value: number | undefined, fallback: number) =>
  typeof value === "number" && Number.isFinite(value) ? value : fallback;
const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));
const within = (
  value: number | undefined,
  fallback: number,
  min: number,
  max: number,
) => clamp(finite(value, fallback), min, max);
const countOf = (count: number | undefined) =>
  Math.round(within(count, COUNT, 1, MAX_COUNT));
const jitterOf = (jitter: number | undefined) =>
  within(jitter, JITTER, 0, 1);

/** Life, lag, launch spread and total length of the burst. */
function trimBurstPlan(
  options: { count?: number; jitter?: number } = {},
) {
  const count = countOf(options.count);
  const stagger = count > 1 ? STAGGER * jitterOf(options.jitter) : 0;
  return {
    life: TRIM_LIFE,
    lag: TRIM_LAG,
    stagger,
    length: TRIM_LIFE + stagger,
  };
}

// `ray:<k>` is the `k`-th ray to fire; which stroke that is comes from the
// seed. The rays are a chain, spread evenly over the launch spread.
const trimBurstTimeline = defineTimeline<
  TrimBurstElementId,
  TrimBurstTimingProps
>(({ count, jitter }) => {
  const n = countOf(count);
  const { stagger } = trimBurstPlan({ count: n, jitter });
  const elements: TimelineElement<TrimBurstElementId>[] = [];
  for (let k = 0; k < n; k++) {
    elements.push({
      id: `ray:${k}`,
      lane: "Rays",
      label: `Ray ${k + 1}`,
      start: n > 1 ? (stagger * k) / (n - 1) : 0,
      length: TRIM_LIFE,
      follows: k > 0 ? `ray:${k - 1}` : undefined,
    });
  }
  return elements;
});

type TrimBurstCap = "round" | "butt";

interface TrimBurstProps {
  x?: number;
  y?: number;
  count?: number;
  innerRadius?: number;
  reach?: number;
  strokeLength?: number;
  weight?: number;
  rotation?: number;
  spread?: number;
  jitter?: number;
  dots?: boolean;
  cap?: TrimBurstCap;
  color?: string;
  seed?: number;
  delay?: number;
  speed?: number;
  className?: string;
  /**
   * Moves, trims or stretches single rays, in launch order, by the ids in
   * `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<TrimBurstElementId>;
}

type Paint = "color" | "className" | "timing";

interface TrimBurstOptions extends Omit<TrimBurstProps, Paint> {
  width?: number;
  height?: number;
  fps?: number;
}

interface TrimBurstStroke {
  index: number;
  angle: number;
  scale: number;
  launch: number;
  /** Place in the launch order: the stroke fires as ray `rank`. */
  rank: number;
}

interface TrimBurstTrim {
  start: number;
  end: number;
  length: number;
}

interface TrimBurstLine {
  index: number;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  width: number;
}

interface TrimBurstDot {
  index: number;
  cx: number;
  cy: number;
  r: number;
}

const trimBurstDefaults: Required<
  Omit<TrimBurstProps, "className" | "timing">
> = {
  x: 0.5,
  y: 0.5,
  count: 8,
  innerRadius: 16,
  reach: 64,
  strokeLength: 56,
  weight: 2,
  rotation: 0,
  spread: 360,
  jitter: 0.5,
  dots: false,
  cap: "round",
  color: "#ffffff",
  seed: 1,
  delay: 0,
  speed: 1,
};

const LIFE = TRIM_LIFE;
const LAG = TRIM_LAG;
const HOLD = 24;
const LEASH = 6;
const WOBBLE = 0.25;
const MAX_STEP = 45;
const SHRINK = 0.45;
const DOT_START = 4;
const DOT_POP = 4;
const DOT_BACK = 1.4;
const DOT_RADIUS = 1.25;
const DOT_GAP = 2;
const MAX_SIZE = 2000;
const MIN_STROKE = 1;
const MIN_WEIGHT = 0.25;
const MAX_WEIGHT = 24;
const VISIBLE = 0.001;
const END_EASE = Easing.bezier(0.16, 1, 0.3, 1);
const START_EASE = Easing.bezier(0.45, 0, 0.55, 1);

const round = (value: number) => Math.round(value * 1000) / 1000;
const rateOf = (speed: number | undefined) =>
  Math.max(0, finite(speed, trimBurstDefaults.speed));
const delayOf = (delay: number | undefined) =>
  Math.max(0, finite(delay, trimBurstDefaults.delay));
const capOf = (cap: string | undefined): TrimBurstCap =>
  cap === "butt" ? cap : "round";

function getTrimBurstTimeline(
  options: Pick<TrimBurstOptions, "count" | "jitter"> = {},
) {
  return trimBurstPlan(options);
}

type TrimBurstTimeline = ReturnType<typeof getTrimBurstTimeline>;

const trimBurstLength = getTrimBurstTimeline().length;

function getTrimBurstDuration(
  options: Pick<TrimBurstOptions, "count" | "jitter" | "delay" | "speed"> = {},
) {
  const rate = rateOf(options.speed);
  const { length } = getTrimBurstTimeline(options);
  const motion = rate === 0 ? 0 : length / rate;
  return Math.ceil(round(delayOf(options.delay) + motion)) + HOLD;
}

function getTrimBurstTime(
  frame: number,
  options: Pick<TrimBurstOptions, "fps" | "delay" | "speed"> = {},
) {
  const fps = Math.max(1, finite(options.fps, 30));
  const elapsed = Math.max(0, finite(frame, 0) - delayOf(options.delay));
  return elapsed * (30 / fps) * rateOf(options.speed);
}

function getTrimBurstEndProgress(time: number) {
  if (Number.isNaN(time) || time <= 0) return 0;
  if (time >= LIFE) return 1;
  return END_EASE(time / LIFE);
}

function getTrimBurstStartProgress(time: number) {
  if (Number.isNaN(time) || time <= LAG) return 0;
  if (time >= LIFE) return 1;
  return START_EASE((time - LAG) / (LIFE - LAG));
}

function getTrimBurstLeash(gap: number, strokeLength: number) {
  if (!(gap > 0 && strokeLength > 0)) return 0;
  return gap / (1 + (gap / strokeLength) ** LEASH) ** (1 / LEASH);
}

function getTrimBurstTrim(
  time: number,
  reach: number,
  strokeLength: number,
): TrimBurstTrim {
  const distance = Math.max(0, finite(reach, 0));
  const end = distance * getTrimBurstEndProgress(time);
  const own = distance * getTrimBurstStartProgress(time);
  const length = getTrimBurstLeash(end - own, strokeLength);
  return { start: end - length, end, length };
}

function getTrimBurstDotScale(time: number) {
  if (Number.isNaN(time) || time <= DOT_START || time >= LIFE) return 0;
  const pop = Math.min(1, (time - DOT_START) / DOT_POP) - 1;
  const grow = 1 + (DOT_BACK + 1) * pop ** 3 + DOT_BACK * pop ** 2;
  const settle = DOT_START + DOT_POP;
  const shrink = clamp((time - settle) / (LIFE - settle), 0, 1);
  return grow * (1 - shrink ** 3);
}

function getTrimBurstStrokes(
  options: Pick<
    TrimBurstOptions,
    "count" | "rotation" | "spread" | "jitter" | "seed"
  > = {},
): TrimBurstStroke[] {
  const count = countOf(options.count);
  const rotation = finite(options.rotation, trimBurstDefaults.rotation);
  const spread = within(options.spread, trimBurstDefaults.spread, 0, 360);
  const jitter = jitterOf(options.jitter);
  const seed = finite(options.seed, trimBurstDefaults.seed);
  const fan = spread < 360 && count > 1;
  const step = fan ? spread / (count - 1) : 360 / count;
  const first = fan ? rotation - spread / 2 : rotation;
  const wobble = WOBBLE * jitter * Math.min(step, MAX_STEP);
  const { stagger } = getTrimBurstTimeline({ count, jitter });
  const keys = Array.from({ length: count }, (_, index) =>
    random(`trim-burst-${seed}-order-${index}`),
  );
  const order = keys.map((_, index) => index);
  order.sort((a, b) => keys[a] - keys[b]);
  const ranks: number[] = [];
  for (const [position, index] of order.entries()) ranks[index] = position;
  return keys.map((_, index) => {
    const turn = random(`trim-burst-${seed}-angle-${index}`) * 2 - 1;
    const shrink = random(`trim-burst-${seed}-scale-${index}`);
    return {
      index,
      angle: first + index * step + turn * wobble,
      scale: 1 - SHRINK * jitter * shrink,
      launch: count > 1 ? (stagger * ranks[index]) / (count - 1) : 0,
      rank: ranks[index],
    };
  });
}

function getTrimBurstState(
  frame: number,
  options: TrimBurstOptions = {},
  strokes: TrimBurstStroke[] = getTrimBurstStrokes(options),
  /**
   * Each ray's span by launch rank, from the component's timeline; without
   * it a stroke fires at its `launch` and lives the default life.
   */
  rays?: readonly { start: number; length: number }[],
) {
  const fallback = trimBurstDefaults;
  const width = Math.max(1, finite(options.width, 1280));
  const height = Math.max(1, finite(options.height, 720));
  const unit = height / 720;
  const time = getTrimBurstTime(frame, options);
  const originX = finite(options.x, fallback.x) * width;
  const originY = finite(options.y, fallback.y) * height;
  const inner = within(options.innerRadius, fallback.innerRadius, 0, MAX_SIZE);
  const reach = within(options.reach, fallback.reach, 0, MAX_SIZE);
  const strokeLength = within(
    options.strokeLength,
    fallback.strokeLength,
    MIN_STROKE,
    MAX_SIZE,
  );
  const size = within(options.weight, fallback.weight, MIN_WEIGHT, MAX_WEIGHT);
  const offset = inner * unit;
  const weight = size * unit;
  const gap = DOT_GAP * weight;
  const radius = DOT_RADIUS * weight;
  const lines: TrimBurstLine[] = [];
  const dots: TrimBurstDot[] = [];
  for (const stroke of strokes) {
    const ray = rays?.[stroke.rank];
    // A resized ray plays its whole life over its new length; the factor is
    // exactly 1 without `timing`.
    const local = !ray
      ? time - stroke.launch
      : ray.length > 0
        ? (time - ray.start) * (LIFE / ray.length)
        : time >= ray.start
          ? LIFE
          : 0;
    const trim = getTrimBurstTrim(
      local,
      reach * unit * stroke.scale,
      strokeLength * unit * stroke.scale,
    );
    const angle = (stroke.angle * Math.PI) / 180;
    const dx = Math.sin(angle);
    const dy = -Math.cos(angle);
    const along = (distance: number) => ({
      x: round(originX + dx * (offset + distance)),
      y: round(originY + dy * (offset + distance)),
    });
    if (trim.length > VISIBLE) {
      const from = along(trim.start);
      const to = along(trim.end);
      lines.push({
        index: stroke.index,
        x1: from.x,
        y1: from.y,
        x2: to.x,
        y2: to.y,
        width: round(Math.min(weight, trim.length)),
      });
    }
    const pop = options.dots === true ? getTrimBurstDotScale(local) : 0;
    if (pop > 0) {
      const center = along(trim.end + gap + radius);
      dots.push({
        index: stroke.index,
        cx: center.x,
        cy: center.y,
        r: round(radius * pop),
      });
    }
  }
  return {
    width,
    height,
    unit,
    time,
    originX,
    originY,
    weight,
    cap: capOf(options.cap),
    lines,
    dots,
  };
}

type TrimBurstState = ReturnType<typeof getTrimBurstState>;

function TrimBurstBase(props: TrimBurstProps) {
  const {
    x = trimBurstDefaults.x,
    y = trimBurstDefaults.y,
    count = trimBurstDefaults.count,
    innerRadius = trimBurstDefaults.innerRadius,
    reach = trimBurstDefaults.reach,
    strokeLength = trimBurstDefaults.strokeLength,
    weight = trimBurstDefaults.weight,
    rotation = trimBurstDefaults.rotation,
    spread = trimBurstDefaults.spread,
    jitter = trimBurstDefaults.jitter,
    dots = trimBurstDefaults.dots,
    cap = trimBurstDefaults.cap,
    color = trimBurstDefaults.color,
    seed = trimBurstDefaults.seed,
    delay = trimBurstDefaults.delay,
    speed = trimBurstDefaults.speed,
    className,
    timing,
  } = props;
  const frame = useSceneFrame();
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    trimBurstTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const rays = useMemo(() => tl.lane("Rays"), [tl]);
  const strokes = useMemo(
    () => getTrimBurstStrokes({ count, rotation, spread, jitter, seed }),
    [count, rotation, spread, jitter, seed],
  );
  const state = getTrimBurstState(
    frame,
    {
      width,
      height,
      fps,
      x,
      y,
      innerRadius,
      reach,
      strokeLength,
      weight,
      dots,
      cap,
      delay,
      speed,
    },
    strokes,
    rays,
  );

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label="Trim burst"
        style={{ display: "block", overflow: "visible" }}
      >
        <g fill="none" stroke={color} strokeLinecap={state.cap}>
          {state.lines.map((line) => (
            <line
              key={line.index}
              x1={line.x1}
              y1={line.y1}
              x2={line.x2}
              y2={line.y2}
              strokeWidth={line.width}
            />
          ))}
        </g>
        <g fill={color}>
          {state.dots.map((dot) => (
            <circle key={dot.index} cx={dot.cx} cy={dot.cy} r={dot.r} />
          ))}
        </g>
      </svg>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  count: {
    type: "number",
    default: 8,
    min: 1,
    max: 24,
    step: 1,
    description: "Strokes",
    hiddenFromList: false,
  },
  innerRadius: {
    type: "number",
    default: 16,
    min: 0,
    max: 160,
    step: 1,
    description: "Inner radius",
    hiddenFromList: false,
  },
